function tabPrice(it){const aps=apStats(),def=defVals(it);const vp=it.vars.filter(v=>v.pr||optsOf(v).some(o=>o&&o.pr));
 const prows=[].concat(vp.map(v=>[v.l,v.pr?"Turned on":"Per choice",v.pr?money(v.pr):optsOf(v).filter(o=>o.pr).map(o=>E(o.v)+" "+money(o.pr)).join(", ")]),(it.pr||[]).map(p=>[p[0],condText(p[1],it),"+"+money(p[2])]));
 const used=uniq(it.appr.map(a=>a.kind));const kinds=["Cost","Software","Region","Role level","Security tier","Budget owner","Worker type","Data","Vendor","Always"];
 const rows=it.appr.map(a=>{const o=aps[it.id+":"+a.id]||{n:0,ok:0,rej:0,pend:0,w:[]};const tot=rollup(it).n;return `<tr><td><b>${E(a.id)}</b></td><td><b>${E(a.n)}</b><small class="muted">${E(a.why)}</small></td><td><span class="pill ${a.kind==="Always"?"mute":"info"}">${E(a.kind)}</span></td><td>${E(condText(a.when,it))}</td><td>${E((RESOLVE[a.who]||{n:a.who.replace("person:","")}).n)}<small class="muted">${a.who.startsWith("person:")?"A named person":"Resolved from data at request time"}</small></td><td class="num">${N(o.n)} <span class="muted small">of ${N(tot)}</span></td><td class="num">${o.w.length?hh(med(o.w)):"none yet"}</td><td class="num">${o.rej?pc(o.rej,o.ok+o.rej)+"%":"0%"}</td></tr>`}).join("");
 return `<div class="grid g2 svc-dg">${card("Price","What the requester sees charged back. Choices add to the base; rules add when a condition is true.",prows.length?`<div class="tscroll"><table class="svc-t"><thead><tr><th>Component</th><th>Applies</th><th>Amount</th></tr></thead><tbody>${prows.map(p=>`<tr><td>${E(p[0])}</td><td>${E(p[1])}</td><td class="num">${p[2]}</td></tr>`).join("")}</tbody></table></div>`:`<p class="muted">No charge. This item is free to request.</p>`,`<span class="pill metric">Default ${money(defPrice(it))}</span>`)}
 ${card("Approval triggers in use","Approvals are decided by data on the request, not hard-coded names. The same item can need none, one or several approvals.",`<div class="row svc-kinds">${kinds.map(k=>`<span class="pill ${used.includes(k)?"info":"mute"}" title="${used.includes(k)?"This item has a rule of this kind":"Not used by this item"}">${E(k)}</span>`).join("")}</div><p class="muted small">Same person for two rules? They approve once. Requester is the approver? It goes to their manager instead. Contractors resolve through their contract sponsor.</p>${stdChip("itil5","Approvals are controls placed inside the value stream, only where the risk or cost justifies them.")}`)}</div>
 ${card("Approval rules",`${it.appr.length} rules. The last columns come from every request so far, so you can see which rules fire often, which slow things down and which ones people reject.`,`<div class="tscroll"><table class="svc-t"><thead><tr><th>Id</th><th>Rule</th><th>Kind</th><th>Fires when</th><th>Approver</th><th>Fired</th><th>Median wait</th><th>Rejected</th></tr></thead><tbody>${rows}</tbody></table></div>`,`<button class="btn" data-svc="design|${it.id}">Edit rules</button>`)}`}

function reqStepList(it){const tpl=tplOf(it.flow).filter(s=>s.rv&&s.type!=="sub"&&s.id!=="s1"),seen=[];tpl.forEach(s=>{if(!seen.includes(s.rv))seen.push(s.rv)});return `<ol class="svc-trk">${seen.map((k,i)=>`<li class="wait"><i>${i+1}</i><span><b>${E(k)}</b><small class="muted">What the requester sees</small></span></li>`).join("")}</ol>`}
