 const opt=(k,l,vals)=>`<div class="svc-vrow"><b>${l}</b><div class="row">${vals.map(x=>`<button class="chip" data-svc="vis|${it.id}|${k}|${x[0]}" aria-pressed="${v[k]===x[0]}">${x[1]}</button>`).join("")}</div></div>`;
