function reqAnswers(r){const it=ITEM(r.item),c=ctxOf(it,r.vals,r.for,r.requester);return `<dl class="kv">${visVars(it,r.vals,c).map(v=>{let x=r.vals[v.k];if(x==null||x===""||(Array.isArray(x)&&!x.length))return"";return `<dt>${E(v.l)}</dt><dd>${E(Array.isArray(x)?x.join(", "):x===true?"Yes":x===false?"No":String(x))}</dd>`}).join("")}</dl>`}
