const fromPrice=it=>{const p=defPrice(it);return p?"from "+money(p):"No charge"};
function priceTag(it){const p=defPrice(it);return `<span class="pill ${p?"metric":"good"}">${p?"from "+money(p):"No charge"}</span>`}
function pItemCard(it,big){const ap=it.appr.length,r=rollup(it);return `<button class="svc-pcard glass ${big?"big":""}" data-svc="pitem|${it.id}"><span class="svc-pcart">${(ILLS[it.ill]||ILLS.service)()}</span><span class="svc-pct"><b>${E(it.n)}</b><span class="muted small">${E(it.short)}</span></span><span class="row small">${priceTag(it)}<span class="pill mute">${E(it.est)}</span>${ap>1?`<span class="pill info">Needs approval</span>`:""}${r.xla?`<span class="pill good" title="Average rating from people who ordered it">${r.xla} / 5</span>`:""}</span></button>`}
function stagesOf(r){const it=ITEM(r.item),P=proj(r),tpl=tplOf(it.flow),sk=new Set(r.sk);const vis=tpl.filter(s=>s.rv&&!sk.has(s.id)&&s.type!=="sub"&&s.id!=="s1"),seen=[];vis.forEach(s=>{if(!seen.includes(s.rv))seen.push(s.rv)});
 const st=seen.map(k=>{const g=vis.filter(x=>x.rv===k);return {k,st:g.every(x=>P[x.id]&&P[x.id].st==="done")?"done":g.some(x=>P[x.id]&&P[x.id].st==="active")?"active":"wait"}});return st}
