function sitText(r){const it=ITEM(r.item),w=r.w[0];if(r.state==="deployed"||r.state==="decommissioned"||r.state==="rejected")return"";if(it.vis.assignee==="hidden")return"";if(r.state==="approved")return"Scheduled to start "+fd(r.startAt);if(!w)return"With our automation";return it.vis.assignee==="person"&&w.k==="person"?"With "+w.n:w.k==="team"?"With "+w.n:w.role==="Approver"?"Waiting for "+(it.vis.approvers==="names"?w.n:"an approver"):w.k==="person"?"With the "+((who(w.n)||{}).team||"service")+" team":"With "+w.n}
function myCard(r){const it=ITEM(r.item),p=progOf(r),sit=sitText(r),due=it.vis.sla==="hidden"||r.done||r.state==="rejected"?"":"Expected "+fd(NOW+Math.max(0,it.slaH-r.slaUsed)*HR*1.3);
 return `<button class="svc-mycard glass" data-svc="my|${r.id}"><span class="row sp"><b>${E(it.n)}</b>${stPill(r.state)}</span><span class="muted small">${E(r.id)}${r.for!==ME?" for "+E(r.for):""} · opened ${fd(r.created)}</span><span class="svc-prog" role="img" aria-label="${p.pct} percent complete"><i style="width:${p.pct}%"></i></span><span class="row sp small"><span><b>${E(p.cur)}</b>${sit?" · "+E(sit):""}</span><span class="muted">${E(due)}</span></span></button>`}
function mineOf(){return REQS.filter(r=>r.requester===ME||r.for===ME).sort((a,b)=>{const o=x=>x.state==="deployed"||x.state==="decommissioned"||x.state==="rejected"?1:0;return o(a)-o(b)||b.created-a.created})}
